+/* Work Entry & Reference Cards */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e8e8e8;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.work-entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h3 {
+    margin: 0;
+    color: #444;
+}
+
+/* Buttons */
+.form-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-next,
+.btn-submit {
+    padding: 0.75rem 2rem;
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    font-size: 1rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+    margin-left: auto;
+}
+
+.btn-next:hover,
+.btn-submit:hover {
+    background: #3451d1;
+}
+
+.btn-next:disabled,
+.btn-submit:disabled {
+    background: #a0a0a0;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    padding: 0.75rem 2rem;
+    background: #fff;
+    color: #666;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+    font-size: 1rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-back:hover {
+    background: #f5f5f5;
+    border-color: #bbb;
+}
+
+.btn-add {
+    padding: 0.6rem 1.25rem;
+    background: #fff;
+    color: #4361ee;
+    border: 1px dashed #4361ee;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    margin-bottom: 1rem;
+    transition: all 0.2s;
+}
+
+.btn-add:hover {
+    background: #f0f4ff;
+}
+
+.btn-remove {
+    padding: 0.4rem 0.75rem;
+    background: #fff;
+    color: #e74c3c;
+    border: 1px solid #e74c3c;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-remove:hover {
+    background: #fff5f5;
+}
+
+.btn-edit {
+    padding: 0.3rem 0.75rem;
+    background: transparent;
+    color: #4361ee;
+    border: 1px solid #4361ee;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-edit:hover {
+    background: #f0f4ff;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 250px !important;
+}
+
+.character-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #888;
+    margin-top: 0.5rem;
+}
+
+.character-count.near-limit {
+    color: #e67e22;
+    font-weight: 500;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #e8e8e8;
+    border-radius: 8px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    color: #333;
+}
+
+.review-content p {
+    margin: 0.3rem 0;
+    color: #555;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-description {
+    font-style: italic;
+    color: #777 !important;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    line-height: 1.6;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.success-icon {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    background: #2ecc71;
+    color: #fff;
+    font-size: 2.5rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1.5rem;
+}
+
+.submission-confirmation h2 {
+    color: #2ecc71;
+}
+
+.application-id {
+    font-size: 1.1rem;
+    margin-top: 1rem;
+    padding: 1rem;
+    background: #f0f9f4;
+    border-radius: 8px;
+    display: inline-block;
+}
